queries.cql:
// CrowdStrike CQL for BPH ASN Connection Correlation
// Detects traffic to known BPH ASNs, NiceNIC-registered domains, or Dynamic DNS abuse
#event_simpleName=DnsRequest OR #event_simpleName=NetworkConnectIP4
| bph_asn_match := destination_asn IN [
    "AS152194", "AS214351", "AS213194", "AS214943", "AS34985",
    "AS48589", "AS49217", "AS214940", "AS140224",
    "AS200019", "AS49042", "AS45839"
  ]
| nicenic_match := domain_registrar = /nicenic/i
| dyndns_match := DomainName = /\.(afraid\.org|mooo\.com|hopto\.org|zapto\.org|sytes\.net)$/i
| where bph_asn_match OR nicenic_match OR dyndns_match
| match_type := case {
    bph_asn_match | "bph_asn";
    nicenic_match | "nicenic_registrar";
    dyndns_match  | "dynamic_dns";
  }
| groupBy([ComputerName, DomainName, destination_asn, match_type], function=[
    count(aid, as=connection_count),
    collect([src_ip, dst_ip, answer])
  ])
| sort(connection_count, order=desc)
